392→export async function freshVerifySandbox(repoRoot, label, sha, opts = {}) {
393→  let fullSha;
394→  try {
395→    fullSha = sh('git', ['rev-parse', '--verify', `${sha}^{commit}`], repoRoot);
396→  } catch {
397→    throw new InvalidShaError(`freshVerifySandbox: "${sha}" does not resolve to a commit in ${repoRoot}`);
398→  }
399→  // Validate every source before registering a worktree. Invalid configuration therefore cannot
400→  // create a detached checkout that no caller has a cleanup handle for.
401→  const sources = dependencySources(repoRoot, opts.dependencyDirs ?? []);
402→  const sparsePaths = sparseProjection(opts.sparsePaths ?? []);
403→
404→  const verifyRoot = join(repoRoot, '.baton', 'verify');
405→  mkdirSync(verifyRoot, { recursive: true });
406→  const suffix = randomBytes(4).toString('hex');
407→  const dir = join(verifyRoot, `${label}-${suffix}`);
408→  let registered = false;
409→
410→  const cleanup = async () => {
411→    if (registered || existsSync(dir)) {
412→      try {
413→        sh('git', ['worktree', 'remove', '--force', dir], repoRoot);
414→      } catch {
415→        rmSync(dir, { recursive: true, force: true });
416→      }
417→    }
418→    try { sh('git', ['worktree', 'prune'], repoRoot); } catch { /* best-effort */ }
419→  };
420→
421→  // Source stays commit-fresh while explicitly configured installed dependencies are copied into
422→  // the sandbox. Never symlink/hardlink the main checkout: the pinned verification command must
423→  // not be able to mutate the orchestrator's toolchain through its dependency path. Any copy
424→  // failure removes and prunes the worktree before the error escapes.
425→  const copiedDependencies = [];
426→  try {
427→    sh('git', ['worktree', 'add', '--detach', ...(sparsePaths.length ? ['--no-checkout'] : []), dir, fullSha], repoRoot);
428→    registered = true;
429→    if (sparsePaths.length) {
430→      gitFile(['sparse-checkout', 'set', '--no-cone', '--stdin'], dir, { input: `${sparsePaths.map((path) => `/${path}`).join('\n')}\n`, encoding: 'utf8' });
431→      gitFile(['checkout', '--detach', fullSha], dir, { stdio: 'pipe' });
432→    }
433→    copiedDependencies.push(...materializeDependencies(dir, sources));
434→  } catch (err) {
435→    await cleanup();
436→    throw err;
437→  }
438→
439→  logEvent(opts, 'worktree', 'worktree.verify_sandbox_created', { dir, sha: fullSha, label, copiedDependencies, sparsePaths });
