50→
51→function localGitEnv() {
52→  const env = {}; for (const [key, value] of Object.entries(process.env)) if (!key.startsWith('GIT_')) env[key] = value;
53→  return { ...env, GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: '/dev/null' };
54→}
55→
56→function localGit(args, cwd, opts = {}) { return execFileSync('git', args, { ...opts, cwd, env: localGitEnv() }); }
57→
58→/** worktree.mjs's real functions wrapped into the coordinator's manager interface. */
59→function worktreeManager(repoRoot, opts = {}) {
60→  return {
61→    async create(taskId) {
62→      const base = await worktreeMod.pinBaseSha(repoRoot, {});
63→      const r = await worktreeMod.createFromBase(repoRoot, taskId, base.sha, { dependencyDirs: opts.workerDependencyDirs ?? [] });
64→      return { path: r.dir, branch: r.branch, baseSha: r.baseSha };
65→    },
66→    async capture(worktreePath, opts = {}) {
67→      return worktreeMod.captureCommit(repoRoot, basename(worktreePath), { vendor: opts.vendor, model: opts.model, effort: opts.effort });
68→    },
69→    async createVerifyWorktree(taskId, sha) {
70→      const r = await worktreeMod.freshVerifySandbox(repoRoot, taskId, sha, { dependencyDirs: opts.verifyDependencyDirs ?? [], sparsePaths: opts.verifySparsePaths ?? [] });
71→      return { path: r.dir ?? r.path };
72→    },
73→    async createBaseVerifyWorktree(taskId, sha) {
74→      const r = await worktreeMod.freshVerifySandbox(repoRoot, `${taskId}-base`, sha, { dependencyDirs: opts.verifyDependencyDirs ?? [], sparsePaths: opts.verifySparsePaths ?? [] });
75→      return { path: r.dir ?? r.path };
76→    },
77→    async changedLines(baseSha, resultSha) {
78→      return worktreeMod.changedLines(repoRoot, baseSha, resultSha);
79→    },
80→    async integrate(sha, opts = {}) {
81→      const strategy = opts.strategy ?? 'ff-only';
82→      if (strategy !== 'ff-only') throw new Error(`unsupported integration strategy: ${strategy}`);
83→      const dirty = localGit(['status', '--porcelain'], repoRoot, { encoding: 'utf8' }).trim();
84→      if (dirty) throw new Error('main checkout is dirty');
85→      const beforeSha = localGit(['rev-parse', 'HEAD'], repoRoot, { encoding: 'utf8' }).trim();
86→      localGit(['merge', '--ff-only', sha], repoRoot, { stdio: 'pipe' });
87→      const afterSha = localGit(['rev-parse', 'HEAD'], repoRoot, { encoding: 'utf8' }).trim();
88→      return { beforeSha, resultSha: sha, afterSha };
89→    },
90→    async stageStructuredIntegration(taskId, sha) {
91→      return worktreeMod.stageStructuredIntegration(repoRoot, taskId, sha, { resolver: opts.structuredMerge });
92→    },
93→    async finalizeStructuredIntegration(stage) { return worktreeMod.finalizeStructuredIntegration(repoRoot, stage); },
94→    async inspectStructuredIntegration(stage) { return worktreeMod.inspectStructuredIntegration(repoRoot, stage); },
95→    async removeStructuredIntegration(stage) { return worktreeMod.removeStructuredIntegration(repoRoot, stage); },
96→    async retainResult(sha) {
97→      const ref = `refs/baton/results/${sha}`;
98→      localGit(['update-ref', ref, sha], repoRoot, { stdio: 'ignore' });
99→      return ref;
100→    },
101→    async releaseResult(ref) {
102→      localGit(['update-ref', '-d', ref], repoRoot, { stdio: 'ignore' });
103→    },
104→    async removeVerifyWorktree(verifyPath) {
105→      try { localGit(['worktree', 'remove', '--force', verifyPath], repoRoot, { stdio: 'ignore' }); } catch { /* noop */ }
106→      try { rmSync(verifyPath, { recursive: true, force: true }); } catch { /* noop */ }
107→    },
108→    // Terminal policy cleanup owns non-evidence task branches as well as their checkout/metadata.
109→    async remove(taskId) { try { await worktreeMod.reap(repoRoot, taskId, { force: true, deleteBranch: true }); } catch { /* noop */ } },
110→    async validateSessionContext(context) {
111→      try {
112→        if (!existsSync(context.worktree)) return { ok: false, reason: 'session worktree no longer exists' };
113→        const root = realpathSync(repoRoot);
114→        const worktree = realpathSync(context.worktree);
115→        const managedRoot = realpathSync(join(repoRoot, '.baton', 'wt'));
116→        if (context.repoRoot && realpathSync(context.repoRoot) !== root) return { ok: false, reason: 'session repository identity mismatch' };
117→        if (worktree !== managedRoot && !worktree.startsWith(`${managedRoot}${sep}`)) return { ok: false, reason: 'session worktree is outside Baton ownership' };
118→        if (context.ownerTaskId && basename(worktree) !== context.ownerTaskId) return { ok: false, reason: 'session worktree owner mismatch' };
119→        const top = localGit(['rev-parse', '--show-toplevel'], worktree, { encoding: 'utf8' }).trim();
120→        if (realpathSync(top) !== worktree) return { ok: false, reason: 'session path is not the recorded git worktree root' };
121→        if (context.branch) {
122→          const branch = localGit(['branch', '--show-current'], worktree, { encoding: 'utf8' }).trim();
123→          if (branch !== context.branch) return { ok: false, reason: 'session worktree branch mismatch' };
124→        }
125→        if (context.baseSha) {
126→          localGit(['merge-base', '--is-ancestor', context.baseSha, 'HEAD'], worktree, { stdio: 'ignore' });
127→        }
128→        return { ok: true };
129→      } catch (err) {
130→        return { ok: false, reason: `session context validation failed: ${err?.message ?? err}` };
131→      }
132→    },
133→    async reconcile() { try { return await worktreeMod.reconcile(repoRoot, []); } catch { return null; } },
134→  };
135→}
136→
137→/** The real hardened referee in the coordinator's fn contract (maps task.worktree -> workerWorktreeDir, string sandbox -> {dir}). */
138→function refereeFn(task, result, opts) {
139→  const mapped = { ...task, workerWorktreeDir: task.worktree, verification: opts.pinnedVerification };
140→  return verify(mapped, result, { dir: opts.sandbox }, {
141→    ...(opts.baseSandbox ? { baseSandbox: { dir: opts.baseSandbox } } : {}),
142→  });
143→}
144→
145→/**
146→ * Assemble a runnable fleet driver.
147→ * @param {{repoRoot:string, logDir:string, adapters:Record<string,object>, now?:()=>number,
148→ *          approvalTimeoutMs?:number, stopDeadlineMs?:number}} opts
149→ * @returns {{coordinator:Coordinator, story:StoryCompiler, router:AdaptiveRouter, log:Log}}
150→ */
151→export function createDriver(opts) {
152→  const now = opts.now ?? Date.now;
153→  const log = new Log(opts.logDir, () => new Date(now()).toISOString());
154→  const fences = new FenceTable();
155→  const router = new AdaptiveRouter({ mode: 'adaptive', now });
156→  const story = new StoryCompiler({ now });
157→  const runtimeScopes = opts.runtimeScopes ?? new RuntimeIsolation({
158→    repoRoot: opts.repoRoot,
159→    ...(opts.runtimeIsolation ?? {}),
160→  });
161→  const coordination = opts.coordination ?? new CoordinationStore(join(opts.logDir, 'coordination'), {
162→    operationalRead: (worker, seq) => log.read(worker, seq).find((event) => event.seq === seq) ?? null,
163→  });
164→  const publisher = Object.hasOwn(opts, 'publisher') ? opts.publisher : async ({ remote, ref, sha }) => {
165→    execFileSync('git', ['push', '--porcelain', remote, `${sha}:${ref}`], { cwd: opts.repoRoot, stdio: 'ignore' });
166→    return { transport: 'git-push' };
167→  };
168→
169→  // C2/D5: real selection via router.pick(task, candidates) over the ceiling-feasible
170→  // set — no first-fit fallback. `pick()` already returns null when nothing is eligible,
171→  // which is exactly "queue" (the coordinator's own ceiling re-check catches it too).
172→  const route = (task, cards, inFlight) => {
173→    // `cards` is already the coordinator's exact model/effort/session/policy-filtered
174→    // candidate set. Re-expanding from every registered adapter would resurrect rejected
175→    // candidates and dereference absent cards in heterogeneous fleets.
176→    let feasible = Object.keys(cards).filter((v) => (inFlight[v] ?? 0) < cards[v].concurrencyCeiling);
177→    // SC7: the explicit capability tag beats operator folklore — when any feasible card lists
178→    // the task's taskType in nonRefuserFor, restrict to those vendors. Feasibility is computed
179→    // FIRST (a capable-but-saturated vendor never restricts) and an unlisted taskType leaves
180→    // the pool untouched — the restriction can never strand a task.
181→    const capable = feasible.filter((v) => Array.isArray(cards[v].nonRefuserFor) && cards[v].nonRefuserFor.includes(task.taskType));
182→    if (capable.length > 0) feasible = capable;
183→    const candidateKey = (v) => {
184→      return routeTupleKey(cards[v], cards[v].modelSelection?.resolved, cards[v].modelSelection?.resolvedEffort, task.taskType);
185→    };
186→    const candidates = feasible.map((v) => ({
187→      modelVersion: candidateKey(v),
188→      // Read-only migration aliases for router state written before the full
189→      // harness/model/effort tuple became the canonical learning identity.
190→      legacyModelVersions: [
191→        ...(cards[v].modelSelection?.resolved
192→          ? [`${cards[v].harness}@${cards[v].version}#${cards[v].modelSelection.resolved}`]
193→          : []),
194→        `${cards[v].harness}@${cards[v].version}`,
195→      ],
196→      family: cards[v].modelSelection?.family ?? 'default',
197→      concurrencyCeiling: cards[v].concurrencyCeiling,
198→      inFlight: inFlight[v] ?? 0,
199→    }));
200→    const chosen = router.pick(task, candidates);
201→    if (!chosen) return null;
202→    // First-listed feasible vendor wins a modelVersion collision: two adapters CAN share
203→    // harness@version (e.g. one-shot ClaudeCli and session ClaudeSessionCli for the same CLI),
204→    // and a last-wins Map would silently flip which vendor key receives the dispatch.
205→    return feasible.find((v) => candidateKey(v) === chosen) ?? null;
206→  };
207→  route.record = (mv, tt, win) => router.record(mv, tt, win);
208→
209→  const coordinator = new Coordinator({
210→    log, fences,
211→    adapters: opts.adapters,
212→    worktrees: worktreeManager(opts.repoRoot, {
213→      workerDependencyDirs: opts.workerDependencyDirs,
214→      verifyDependencyDirs: opts.verifyDependencyDirs,
215→      verifySparsePaths: opts.verifySparsePaths,
216→      structuredMerge: opts.structuredMerge,
217→    }),
218→    runtimeScopes,
219→    coordination,
220→    repoRoot: opts.repoRoot,
221→    referee: refereeFn,
222→    route,
223→    accept: (verdict, acceptOpts) => accept(verdict, acceptOpts),
224→    acceptOpts: {
225→      requireRedGreen: opts.requireRedGreen ?? false,
226→      requireCoverage: opts.requireCoverage ?? false,
227→      requireMutation: opts.requireMutation ?? false,
228→    },
229→    requireIndependentOracle: opts.requireIndependentOracle ?? false,
230→    publisher,
231→    story: { record: (e) => story.ingest(e) },
232→    now,
233→    approvalTimeoutMs: opts.approvalTimeoutMs ?? 60000,
234→    stopDeadlineMs: opts.stopDeadlineMs ?? 15000,
235→    recoveryTimeoutMs: opts.recoveryTimeoutMs ?? 15000,
236→    budgetPolicy: opts.budgetPolicy,
237→    watchdog: opts.watchdog,
238→  });
239→
240→  return { coordinator, story, router, log, coordination };
241→}
